// tickerFill("{A} zachorował{A?|a} na botulizm", "Mara", "f") -> "Mara zachorowała na botulizm"; English templates only have {A}. gender "n" = masculine form.
function tickerFill(tpl, name, gender) {
  return String(tpl).replace(/\{A\?([^|{}]*)\|([^|{}]*)\}/g, (m, a, b) => (gender === 'f' ? b : a)).replace(/\{A\}/g, name);
}
